int result = LFS_CMP_EQ;
lfs_size_t read_size = std::min(size, hint);
lfs_size_t offset = off;
lfs_size_t remaining = size;

while (remaining > 0) {
    lfs_size_t chunk_size = std::min(read_size, remaining);
    void *read_buffer = lfs_bd_read(lfs, pcache, rcache, block, offset, chunk_size);
    if (read_buffer == nullptr) {
        return LFS_ERR_IO;
    }

    if (std::memcmp(read_buffer, (const char *)buffer + (size - remaining), chunk_size) != 0) {
        if (*((const char *)buffer + (size - remaining)) < *((const char *)read_buffer)) {
            result = LFS_CMP_LT;
        } else {
            result = LFS_CMP_GT;
        }
        break;
    }

    offset += chunk_size;
    remaining -= chunk_size;
}

return result;

